'use client';

import { useState, type ReactNode } from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Dialog } from '@/components/ui/dialog';
import { Field } from '@/components/ui/field';
import { FormError } from '@/components/ui/form-error';
import { Input, Textarea } from '@/components/ui/input';
import type { CatalogItem } from '@/lib/api/types';
import { apiErrorsFor, type FieldErrors } from '@/lib/forms';

/** "BDT 8,500" / "$12.50"; "Price on request" when the item has none. */
export function formatPrice(value: number | null, currency: string): string {
  if (value === null) return 'Price on request';
  try {
    return new Intl.NumberFormat('en', { style: 'currency', currency, minimumFractionDigits: Number.isInteger(value) ? 0 : 2, maximumFractionDigits: 2 }).format(value);
  } catch {
    return `${value} ${currency}`;
  }
}

/** Whether an item can be ordered now, and why not. */
export function AvailabilityBadge({ item }: { item: Pick<CatalogItem, 'available' | 'stock'> }) {
  if (!item.available) return <Badge tone="neutral">Not available</Badge>;
  if (item.stock === null) return <Badge tone="success">Available</Badge>;
  if (item.stock === 0) return <Badge tone="warning">Out of stock</Badge>;
  return <Badge tone="success">In stock · {item.stock}</Badge>;
}

/** "12,400 characters" → "12.4k characters". */
export function formatChars(count: number): string {
  return count >= 1000 ? `${(count / 1000).toLocaleString('en', { maximumFractionDigits: 1 })}k characters` : `${count} characters`;
}

/**
 * Create or rename a catalog or knowledge base: name, description and (catalogs) currency. Errors
 * from the API (a name already used, an invalid currency) land on their fields.
 */
export function NameDialog({
  open,
  onOpenChange,
  title,
  description,
  submitLabel,
  initial,
  withCurrency,
  onSubmit,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: ReactNode;
  submitLabel: string;
  initial?: { name: string; description: string; currency?: string };
  withCurrency?: boolean;
  onSubmit: (value: { name: string; description: string; currency?: string }) => Promise<unknown>;
}) {
  const [name, setName] = useState(initial?.name ?? '');
  const [text, setText] = useState(initial?.description ?? '');
  const [currency, setCurrency] = useState(initial?.currency ?? 'BDT');
  const [errors, setErrors] = useState<FieldErrors>({});
  const [busy, setBusy] = useState(false);

  const submit = async () => {
    const next: FieldErrors = {};
    if (!name.trim()) next.name = 'Give it a name';
    if (withCurrency && !/^[A-Za-z]{3}$/.test(currency.trim())) next.currency = 'Three-letter currency code such as BDT or USD';
    setErrors(next);
    if (Object.keys(next).length) return;
    setBusy(true);
    try {
      await onSubmit({ name: name.trim(), description: text.trim(), ...(withCurrency ? { currency: currency.trim().toUpperCase() } : {}) });
      onOpenChange(false);
    } catch (error) {
      setErrors(apiErrorsFor(error));
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog
      open={open}
      onOpenChange={onOpenChange}
      title={title}
      description={description}
      footer={
        <>
          <Button variant="secondary" onClick={() => onOpenChange(false)} disabled={busy}>
            Cancel
          </Button>
          <Button variant="primary" loading={busy} onClick={() => void submit()}>
            {submitLabel}
          </Button>
        </>
      }
    >
      <form
        className="flex flex-col gap-4"
        onSubmit={(e) => {
          e.preventDefault();
          void submit();
        }}
      >
        <FormError errors={errors} shown={['name', 'currency', 'description']} />
        <Field label="Name" required error={errors.name}>
          {(props) => <Input {...props} value={name} maxLength={100} onChange={(e) => setName(e.target.value)} />}
        </Field>
        {withCurrency ? (
          <Field label="Currency" description="Every price in the catalog is in this currency (ISO code, e.g. BDT, USD)." error={errors.currency}>
            {(props) => <Input {...props} value={currency} maxLength={3} className="w-28 uppercase" onChange={(e) => setCurrency(e.target.value)} />}
          </Field>
        ) : null}
        <Field label="Description" description="For your team; the assistant does not see it." error={errors.description}>
          {(props) => <Textarea {...props} rows={2} value={text} maxLength={1000} onChange={(e) => setText(e.target.value)} />}
        </Field>
        <button type="submit" hidden />
      </form>
    </Dialog>
  );
}
