'use client';

import { Plus, ShoppingBag } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { LoadMore } from '@/components/ui/load-more';
import { PageBody, PageHeader } from '@/components/ui/page';
import { EmptyState, ErrorState, LoadingState } from '@/components/ui/states';
import { Table, TBody, Td, Th, THead, Tr } from '@/components/ui/table';
import { formatNumber, formatRelative } from '@/lib/format';
import { useSession } from '@/lib/session';
import { useCatalogList, useCreateCatalog } from './api';
import { NameDialog } from './shared';

export function CatalogList() {
  const { can } = useSession();
  const router = useRouter();
  const list = useCatalogList();
  const create = useCreateCatalog();
  const [creating, setCreating] = useState(false);
  const canManage = can('knowledge:manage');

  const newButton = canManage ? (
    <Button variant="primary" onClick={() => setCreating(true)}>
      <Plus aria-hidden="true" />
      New catalog
    </Button>
  ) : null;

  return (
    <PageBody>
      <PageHeader
        title="Catalogs"
        description="The products and services your assistants sell and answer about: names, prices and stock. Attach a catalog to an assistant on its Knowledge tab; the assistant never quotes anything that is not here."
        actions={newButton}
      />
      {list.isPending ? (
        <LoadingState label="Loading catalogs…" />
      ) : list.isError ? (
        <ErrorState error={list.error} title="Could not load catalogs" onRetry={() => void list.refetch()} />
      ) : list.items.length === 0 ? (
        <EmptyState icon={<ShoppingBag />} title="No catalogs yet" description="Create a catalog, then import your products from a spreadsheet (CSV) or add them one by one." action={newButton} />
      ) : (
        <>
          <Table label="Catalogs">
            <THead>
              <Tr>
                <Th>Name</Th>
                <Th className="text-right">Items</Th>
                <Th className="hidden sm:table-cell">Currency</Th>
                <Th className="hidden md:table-cell">Used by</Th>
                <Th className="hidden md:table-cell">Updated</Th>
              </Tr>
            </THead>
            <TBody>
              {list.items.map((catalog) => (
                <Tr key={catalog.id}>
                  <Td>
                    <Link href={`/catalogs/${catalog.id}`} className="font-medium text-accent-text underline-offset-4 hover:underline">
                      {catalog.name}
                    </Link>
                    {catalog.description ? <p className="mt-0.5 line-clamp-1 text-xs text-muted">{catalog.description}</p> : null}
                  </Td>
                  <Td className="text-right tabular-nums">{formatNumber(catalog.itemCount)}</Td>
                  <Td className="hidden text-muted sm:table-cell">{catalog.currency}</Td>
                  <Td className="hidden text-muted md:table-cell">{catalog.assistantCount === 1 ? '1 assistant' : `${catalog.assistantCount ?? 0} assistants`}</Td>
                  <Td className="hidden text-muted md:table-cell">{formatRelative(catalog.updatedAt)}</Td>
                </Tr>
              ))}
            </TBody>
          </Table>
          <LoadMore count={list.items.length} noun="catalog" hasNextPage={list.hasNextPage} isFetchingNextPage={list.isFetchingNextPage} fetchNextPage={list.fetchNextPage} />
        </>
      )}
      {creating ? (
        <NameDialog
          open
          onOpenChange={setCreating}
          title="New catalog"
          description="You can import products into it next."
          submitLabel="Create catalog"
          withCurrency
          onSubmit={async (value) => {
            const catalog = await create.mutateAsync(value);
            router.push(`/catalogs/${catalog.id}`);
          }}
        />
      ) : null}
    </PageBody>
  );
}
